const readline = require('readline');
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let inputs = [];
​
rl.on('line', (line) => {
    inputs.push(line);
    if (inputs.length === 2) {
        rl.close();
    }
});
​
rl.on('close', () => {
    let input1 = inputs[0];
    let input2 = inputs[1];
​
    // 按正则表达式分割
    let splitString = input1.split(/[0-9a-f]+/).filter(s => s.length > 0);
​
    if (splitString.length === 0) {
        console.log("Not Found");
        return;
    }
​
    let validChars = new Set(input2);
    let valids = [];
​
    // 取出所有满足条件的有效子串
    splitString.forEach(str => {
        let uniqueChars = new Set(str);
        if (uniqueChars.size <= validChars.size) {
            valids.push(str);
        }
    });
​
    if (valids.length === 0) {
        console.log("Not Found");
        return;
    }
​
    // 自定义排序：唯一字符数优先，字典序降序
    valids.sort((a, b) => {
        let uniqueA = new Set(a).size;
        let uniqueB = new Set(b).size;
​
        if (uniqueA !== uniqueB) {
            return uniqueB - uniqueA;
        }
        return b.localeCompare(a);
    });
​
    console.log(valids[0]);
});
